const e=JSON.parse('[{"id":"110_110010_001","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"國家文官學院辦理各級公務人員考試錄取人員之訓練，其隸屬何機關？","tableData":null,"images":[],"options":[{"key":"A","text":"考選部","imageUrl":null},{"key":"B","text":"銓敘部","imageUrl":null},{"key":"C","text":"公務人員保障暨培訓委員會","imageUrl":null},{"key":"D","text":"行政院人事行政總處","imageUrl":null}],"correctAnswer":"C","explanation":"國家文官學院隸屬於公務人員保障暨培訓委員會，負責辦理各項公務人員訓練事項。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_002","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"依現行「考試院組織法」規定，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"考試院考試委員之名額，定為 7 人至 9 人","imageUrl":null},{"key":"B","text":"考試院院長、副院長及考試委員之任期為 6 年","imageUrl":null},{"key":"C","text":"考試委員具有同一黨籍者，不得超過委員總額二分之一","imageUrl":null},{"key":"D","text":"考試委員赴中國大陸地區兼職者，即喪失考試委員之資格","imageUrl":null}],"correctAnswer":"B","explanation":"依考試院組織法修正規定，院長、副院長及考試委員之任期由6年改為4年。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_003","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"立法院院長的本職是立法委員，由立法委員互選決定","imageUrl":null},{"key":"B","text":"司法院院長的本職是大法官，由總統提名經立法院同意任命之","imageUrl":null},{"key":"C","text":"考試院院長的本職是考試委員，由總統提名經立法院同意任命之","imageUrl":null},{"key":"D","text":"監察院院長的本職是監察委員，由總統提名經立法院同意任命之","imageUrl":null}],"correctAnswer":"C","explanation":"考試院院長職務係由總統提名、立法院同意任命，其法律定位並非以「考試委員」為本職。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_004","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"國營事業機構負責人、經理人派免之審核，係下列那個機關組織法律所定職掌？","tableData":null,"images":[],"options":[{"key":"A","text":"行政院人事行政總處","imageUrl":null},{"key":"B","text":"國家發展委員會","imageUrl":null},{"key":"C","text":"經濟部","imageUrl":null},{"key":"D","text":"銓敘部","imageUrl":null}],"correctAnswer":"D","explanation":"依銓敘部組織法規定，國營事業機構負責人、經理人派免之審核屬於銓敘部的法定職掌。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_005","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"下列何者是政治途徑的公共人事行政所強調的價值？","tableData":null,"images":[],"options":[{"key":"A","text":"回應性","imageUrl":null},{"key":"B","text":"個人權利保障","imageUrl":null},{"key":"C","text":"效率","imageUrl":null},{"key":"D","text":"正當法律程序","imageUrl":null}],"correctAnswer":"A","explanation":"政治途徑強調人事行政應對民意與政策目標展現回應性，以落實民主問責機制。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_006","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"某甲通過警察特考後，目前已任官授階正式執行警察任務，其適用下列何種人事管理制度？","tableData":null,"images":[],"options":[{"key":"A","text":"官職分立制","imageUrl":null},{"key":"B","text":"官職併立制","imageUrl":null},{"key":"C","text":"資位制","imageUrl":null},{"key":"D","text":"聘派制","imageUrl":null}],"correctAnswer":"B","explanation":"我國警察人員人事制度採官職併立制，即同時擁有官階與職務職等。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_007","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"「公務人員行政中立法」第 17 條有關準用人員之規定，下列何者不包括在內？","tableData":null,"images":[],"options":[{"key":"A","text":"未兼行政職務之公立學校教師","imageUrl":null},{"key":"B","text":"各機關及公立學校依法聘用、僱用人員","imageUrl":null},{"key":"C","text":"公營事業對經營政策負有主要決策責任之人員","imageUrl":null},{"key":"D","text":"行政法人有給專任人員","imageUrl":null}],"correctAnswer":"A","explanation":"行政中立法第17條規範準用對象，但「未兼任行政職務之公立學校教師」不在此條列舉之內。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_008","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"依據公務人員陞遷法規定，下列何種人員出缺時，得免除公開甄選之辦理？","tableData":null,"images":[],"options":[{"key":"A","text":"因修正組織編制須安置人員","imageUrl":null},{"key":"B","text":"因修正組織編制須甄審人員","imageUrl":null},{"key":"C","text":"因修正組織編制須派外人員","imageUrl":null},{"key":"D","text":"因修正組織編制須關照人員","imageUrl":null}],"correctAnswer":"A","explanation":"依公務人員陞遷法規定，因修正組織編制須安置之人員出缺時，得免經公開甄選程序。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_009","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"甲擔任行政院某部部長薦任職務機要人員，該部長因健康因素向行政院院長請辭獲准，試問依規定應將甲進行下列何者處置最為適當？","tableData":null,"images":[],"options":[{"key":"A","text":"撤職","imageUrl":null},{"key":"B","text":"免職","imageUrl":null},{"key":"C","text":"轉任","imageUrl":null},{"key":"D","text":"調任","imageUrl":null}],"correctAnswer":"B","explanation":"機要人員隨同任用之長官進退，當該長官辭職獲准時，機要人員應予免職。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_010","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"下列有關職務歸系之敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"職務所歸職系類別應與其職稱性質相當","imageUrl":null},{"key":"B","text":"行政性職稱應歸入行政類職系","imageUrl":null},{"key":"C","text":"技術性職稱應歸入技術類職系","imageUrl":null},{"key":"D","text":"行政性、技術性通用職稱，應歸入一般類職系","imageUrl":null}],"correctAnswer":"D","explanation":"通用職稱應視其職務主要工作性質歸入適當職系，法規中並無一律歸入一般類職系之規定。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_011","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"下列何者非屬公務人員陞遷法中應謹守的主要原則？","tableData":null,"images":[],"options":[{"key":"A","text":"人與事配合","imageUrl":null},{"key":"B","text":"遷調歷練","imageUrl":null},{"key":"C","text":"資績並重","imageUrl":null},{"key":"D","text":"學歷優先","imageUrl":null}],"correctAnswer":"D","explanation":"公務人員陞遷法強調資績並重、人與事配合及遷調歷練，並未將學歷優先列為原則。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_012","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"依公務人員考試法規定，特種考試身心障礙人員考試及格者，服務多少年內，不得轉調申請舉辦特種考試機關及其所屬機關、學校以外之機關、學校任職？","tableData":null,"images":[],"options":[{"key":"A","text":"3 年","imageUrl":null},{"key":"B","text":"6 年","imageUrl":null},{"key":"C","text":"9 年","imageUrl":null},{"key":"D","text":"永久不得轉調","imageUrl":null}],"correctAnswer":"B","explanation":"依現行規定，特種考試身心障礙人員考試及格者，於服務滿6年後始得轉調原機關以外之單位。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_013","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"人事機關（構）依其運作方式及決策層級可以分為多種制度，請問我國的行政院人事行政總處，是屬於下列何種制度？","tableData":null,"images":[],"options":[{"key":"A","text":"委員制","imageUrl":null},{"key":"B","text":"首長制","imageUrl":null},{"key":"C","text":"混合制","imageUrl":null},{"key":"D","text":"輪值制","imageUrl":null}],"correctAnswer":"B","explanation":"行政院人事行政總處為行政院之所屬機關，由人事長領導，決策權集中於單一負責人，屬首長制。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_014","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"甲女通過公務人員普通考試，經訓練期滿後，於 106 年 8 月分發至內政部任職。甲女最快何時才得轉調至其住家附近的國民中學任職？","tableData":null,"images":[],"options":[{"key":"A","text":"108 年 8 月後","imageUrl":null},{"key":"B","text":"109 年 8 月後","imageUrl":null},{"key":"C","text":"110 年 8 月後","imageUrl":null},{"key":"D","text":"112 年 8 月後","imageUrl":null}],"correctAnswer":"B","explanation":"依公務人員考試法，高普考及格者須在原分發機關服務滿3年方可轉調，故為109年8月後。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_015","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"下列何種情況之任用，不需要呈請總統任命？","tableData":null,"images":[],"options":[{"key":"A","text":"普考及格分發初任第三職等辦事員","imageUrl":null},{"key":"B","text":"高考及格分發初任第六職等科員","imageUrl":null},{"key":"C","text":"第九職等科長晉升為簡任第十職等專門委員","imageUrl":null},{"key":"D","text":"第十一職等副司長晉升為第十二職等司長","imageUrl":null}],"correctAnswer":"D","explanation":"簡任第十二職等以上之任用案，由行政院呈請總統任命，其餘人員則非屬此層級規定。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_016","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"中央選舉委員會於 5 月 1 日宣告對甲縣首長 A 之罷免案成立，並於 6 月 15 日公告罷免投票結果。A 在下列那一個時間點之任用或遷調人員係屬違法？","tableData":null,"images":[],"options":[{"key":"A","text":"3 月 25 日","imageUrl":null},{"key":"B","text":"4 月 29 日","imageUrl":null},{"key":"C","text":"5 月 17 日","imageUrl":null},{"key":"D","text":"4 月 17 日","imageUrl":null}],"correctAnswer":"C","explanation":"依規定自罷免案宣告成立（5/1）起至公告投票結果（6/15）止，不得任用遷調人員。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_017","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"現職公務人員之調任規定，下列何項敘述正確？","tableData":null,"images":[],"options":[{"key":"A","text":"簡任第十職等以上人員，在各職系之職務間得予調任","imageUrl":null},{"key":"B","text":"經依法任用人員，除自願者外，不得調任低一個官等之職務","imageUrl":null},{"key":"C","text":"在同官等內調任低職等職務，除自願者外，以調任低二職等之職務為限","imageUrl":null},{"key":"D","text":"非有特殊情形，主管人員得依業務需求，調任本單位之副主管或非主管職務","imageUrl":null}],"correctAnswer":"B","explanation":"現職公務人員依法受職位保障，非經本人自願，不得將其調任至低一官等之職位。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_018","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"透過陞遷引起公務人員的學習動機，與下列那一個理論最相關？","tableData":null,"images":[],"options":[{"key":"A","text":"領導理論","imageUrl":null},{"key":"B","text":"學習心理學","imageUrl":null},{"key":"C","text":"外在報酬理論","imageUrl":null},{"key":"D","text":"目標設定理論","imageUrl":null}],"correctAnswer":"B","explanation":"透過獎勵（如陞遷）誘發動機，符合學習心理學中關於增強與激勵學習行為之原理。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_019","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"有關考績的原則，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"考績結果要保密，絕對不可公開","imageUrl":null},{"key":"B","text":"須有充分的客觀事實資料做為基礎，而非憑長官的主觀印象","imageUrl":null},{"key":"C","text":"工作績效與倫理品行並重","imageUrl":null},{"key":"D","text":"兼顧考核期間與工作表現","imageUrl":null}],"correctAnswer":"A","explanation":"考績原則強調程序公開與公平，適度的回饋與公開（如考績委員會決議）是制度運作的一部分。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_020","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"下列有關考績委員會的敘述，何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"負責公務員考績案之審定","imageUrl":null},{"key":"B","text":"委員任一政黨比例不得低於三分之一","imageUrl":null},{"key":"C","text":"由機關首長擔任主席","imageUrl":null},{"key":"D","text":"機關人事主管人員為當然委員","imageUrl":null}],"correctAnswer":"D","explanation":"依考績委員會組織規程規定，人事主管人員為該委員會之當然委員。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_021","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"我國高階公務人員接受中長期發展性訓練評鑑合格者，依規定要納入人才資料庫，其主要目的為：","tableData":null,"images":[],"options":[{"key":"A","text":"提供機關用人之查詢","imageUrl":null},{"key":"B","text":"做為企業旋轉門之候選人","imageUrl":null},{"key":"C","text":"視同取得簡任官等任用資格","imageUrl":null},{"key":"D","text":"取得資料探勘師的進階資格","imageUrl":null}],"correctAnswer":"A","explanation":"高階公務人員人才資料庫之設置，旨在提供各機關於選補高階職缺時進行查詢與參考。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_022","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"有關公務人員培訓措施，最接近下列何種人力資源的功能？","tableData":null,"images":[],"options":[{"key":"A","text":"紀律管理","imageUrl":null},{"key":"B","text":"工作分析","imageUrl":null},{"key":"C","text":"員額評鑑","imageUrl":null},{"key":"D","text":"組織發展","imageUrl":null}],"correctAnswer":"D","explanation":"培訓藉由提升員工個人能力，進而增進整體組織效能，屬於組織發展的核心範疇。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_023","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"公務人員之俸給係依「公務人員俸給法」行之，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"公務人員之俸給，分本俸（年功俸）及加給","imageUrl":null},{"key":"B","text":"本俸係指各職等人員依法應領取之基本給與","imageUrl":null},{"key":"C","text":"年功俸係指各職等高於本俸最高俸級之給與","imageUrl":null},{"key":"D","text":"加給係指本俸、年功俸以外，因所任職務種類、性質與教育程度之不同，而另加之給與","imageUrl":null}],"correctAnswer":"D","explanation":"加給係因職務種類、性質、服務地區或專業技能而加給，並非根據「教育程度」不同而給予。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_024","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"關於公務人員訓練的各種評鑑方法，下列何者最能展現公務人員受訓的成果？","tableData":null,"images":[],"options":[{"key":"A","text":"受訓時的考試與作業成績","imageUrl":null},{"key":"B","text":"受訓者的滿意度調查","imageUrl":null},{"key":"C","text":"受訓後在工作崗位上的表現","imageUrl":null},{"key":"D","text":"受訓者當年度的受訓時數","imageUrl":null}],"correctAnswer":"C","explanation":"訓練的終極目標在於行為轉化，故「受訓後在工作崗位上的表現」最能體現訓練成果。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_025","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"某甲是一位經常需要跑外勤的人員。當他在外工作時，主管無法直接觀察到他的實際表現；但是當他在辦公室工作時，主管都能感受到他的工作熱情與良好的工作表現。主管依照他內勤工作的表現，判斷他外勤工作表現一定也同樣良好。請問某甲的主管在打考績時最可能犯了什麼謬誤？","tableData":null,"images":[],"options":[{"key":"A","text":"沒有犯錯","imageUrl":null},{"key":"B","text":"趨中的謬誤","imageUrl":null},{"key":"C","text":"暈輪謬誤","imageUrl":null},{"key":"D","text":"過寬或過嚴的謬誤","imageUrl":null}],"correctAnswer":"C","explanation":"暈輪謬誤係指評分者因受評人某一項優異特質之影響，進而對其所有表現給予一致評價。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_026","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"公餘進修之公務人員，於核定進修期間，其進修費用，每學期每人最高補助新臺幣多少元？","tableData":null,"images":[],"options":[{"key":"A","text":"一萬元","imageUrl":null},{"key":"B","text":"四萬元","imageUrl":null},{"key":"C","text":"三萬元","imageUrl":null},{"key":"D","text":"二萬元","imageUrl":null}],"correctAnswer":"D","explanation":"依現行規定，公務人員公餘進修费用補助最高限額為每學期每人新臺幣二萬元。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_027","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"各機關學校選送國外進修之公務人員，其進修期間，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"經中央一級機關專案核定國外進修人員，其進修期限最長為四年","imageUrl":null},{"key":"B","text":"專題研究期間為六個月以內。必要時，得依規定申請延長，延長期間最長為三個月","imageUrl":null},{"key":"C","text":"入學進修期間為一年以內。但經各主管機關核准延長者，延長期間最長為一年","imageUrl":null},{"key":"D","text":"選修學分期間為六個月以內。但經各主管機關核准延長者，延長期間最長為一年","imageUrl":null}],"correctAnswer":"D","explanation":"選修學分之進修期限應有其明確規範，其「延長期間最長為一年」之敘述與法規不符。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_028","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"公務人員考績案，送何機關銓敘審定時，如發現有違反考績法規情事者，應照原送案程序，退還原考績機關另為適法之處分？","tableData":null,"images":[],"options":[{"key":"A","text":"銓敘部","imageUrl":null},{"key":"B","text":"考選部","imageUrl":null},{"key":"C","text":"公務人員保障暨培訓委員會","imageUrl":null},{"key":"D","text":"行政院人事行政總處","imageUrl":null}],"correctAnswer":"A","explanation":"銓敘部依法掌理公務人員考績之銓敘審定，具備審核考績合法性並退還違法案件之職權。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_029","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"有關初任各官等職務之人員，其等級起敘之敘述，下列何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"高等考試之二級考試及格者，初任薦任職務時，敘薦任第九職等本俸一級","imageUrl":null},{"key":"B","text":"普通考試及格者，敘委任第三職等本俸一級","imageUrl":null},{"key":"C","text":"初等考試及格者，敘委任第一職等本俸一級","imageUrl":null},{"key":"D","text":"高等考試之三級考試及格者，初任薦任職務時，敘薦任第六職等本俸一級","imageUrl":null}],"correctAnswer":"A","explanation":"高考二級考試及格者，初任薦任職務時，應敘薦任第七職等本俸一級，而非第九職等。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_030","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"從人力訓練機構的作業角度而言，辦理培訓課程與管理的首要步驟是：","tableData":null,"images":[],"options":[{"key":"A","text":"發展與執行培訓課程","imageUrl":null},{"key":"B","text":"培訓課程規劃","imageUrl":null},{"key":"C","text":"培訓需求分析","imageUrl":null},{"key":"D","text":"培訓績效評估","imageUrl":null}],"correctAnswer":"C","explanation":"訓練循環（ADDIE）的第一步為需求分析（Analysis），旨在確定組織與個人的學習缺口。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_031","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"某甲配合機關裁撤而辦理退休，依法該員最高得獲加發幾個月的俸給總額慰助金？","tableData":null,"images":[],"options":[{"key":"A","text":"三個月","imageUrl":null},{"key":"B","text":"五個月","imageUrl":null},{"key":"C","text":"七個月","imageUrl":null},{"key":"D","text":"九個月","imageUrl":null}],"correctAnswer":"C","explanation":"依公務人員退休資遣撫卹法規定，配合機關裁撤退休者，最高得加發七個月之俸給總額慰助金。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_032","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"關於「為了避免在選舉期間必須表態，以及選後面臨秋後算帳的窘境」之敘述，最符合公務人員保障制度下列何項功能？","tableData":null,"images":[],"options":[{"key":"A","text":"維護基本人權","imageUrl":null},{"key":"B","text":"保障公務人員合法權益","imageUrl":null},{"key":"C","text":"節制行政權運作","imageUrl":null},{"key":"D","text":"確保行政中立","imageUrl":null}],"correctAnswer":"D","explanation":"保障制度能使公務員免於政治報復或被迫表態，進而確保行政中立，達成政黨更迭下之穩定。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_033","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"下列何者不屬於公務員懲戒法規定之懲戒處分？","tableData":null,"images":[],"options":[{"key":"A","text":"撤職","imageUrl":null},{"key":"B","text":"休職","imageUrl":null},{"key":"C","text":"解聘","imageUrl":null},{"key":"D","text":"免除職務","imageUrl":null}],"correctAnswer":"C","explanation":"懲戒處分包括撤職、休職、免除職務等，而「解聘」係依聘用契約終止之行為。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_034","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"有關公教人員保險之相關規定，下列何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"銓敘部為主管機關","imageUrl":null},{"key":"B","text":"政府對公、私立學校編制內之有給專任教職員保險費之補助比率有所不同","imageUrl":null},{"key":"C","text":"私立學校不是公教人員保險法規範範圍","imageUrl":null},{"key":"D","text":"被保險人應自付保險費 35%","imageUrl":null}],"correctAnswer":"C","explanation":"私立學校編制內有給專任教職員依法為公教人員保險之被保險人，屬法規適用範圍。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_035","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"公務人員保險的承保機關為下列何者？","tableData":null,"images":[],"options":[{"key":"A","text":"臺灣銀行","imageUrl":null},{"key":"B","text":"中央銀行","imageUrl":null},{"key":"C","text":"中央保險局","imageUrl":null},{"key":"D","text":"中國信託銀行","imageUrl":null}],"correctAnswer":"A","explanation":"依公教人員保險法規定，政府委託臺灣銀行辦理公教人員保險業務。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_036","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"公務人員協會如果發生妨害公共利益的情事，主管機關可對該協會作成何種行政處分？","tableData":null,"images":[],"options":[{"key":"A","text":"申誡","imageUrl":null},{"key":"B","text":"警告","imageUrl":null},{"key":"C","text":"處以罰鍰","imageUrl":null},{"key":"D","text":"廢止其設立許可","imageUrl":null}],"correctAnswer":"B","explanation":"公務人員協會法規定，協會如有妨害公共利益，主管機關得給予警告處分。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_037","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"根據公務人員保障法，政府機關應提供執行職務所需條件，下列何者最符合實體保障事項？","tableData":null,"images":[],"options":[{"key":"A","text":"俸給之保障","imageUrl":null},{"key":"B","text":"必要機具設備及良好工作環境","imageUrl":null},{"key":"C","text":"身分保障","imageUrl":null},{"key":"D","text":"官等、職等之保障","imageUrl":null}],"correctAnswer":"B","explanation":"機關提供必要之機具設備與環境，屬於公務人員保障法規定之執行職務保障事項。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_038","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"下列何者最不是確定給付制度（defined benefit system）的優點？","tableData":null,"images":[],"options":[{"key":"A","text":"受僱者擁有自己的個人帳戶","imageUrl":null},{"key":"B","text":"給付水準具預測性","imageUrl":null},{"key":"C","text":"退休者不用擔心通貨膨脹","imageUrl":null},{"key":"D","text":"較不會出現替代率過低之問題","imageUrl":null}],"correctAnswer":"A","explanation":"擁有個人帳戶是「確定提撥制」的特徵，而非確定給付制度的優點。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_039","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"下列有關特別權力關係之敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"當事人地位不對等","imageUrl":null},{"key":"B","text":"相對人義務不確定","imageUrl":null},{"key":"C","text":"有特別規則","imageUrl":null},{"key":"D","text":"得提起行政爭訟","imageUrl":null}],"correctAnswer":"D","explanation":"傳統特別權力關係理論認為受規範者不得提起訴訟，此與現代法治觀點不合且為題幹所述之錯誤點。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_040","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"甲任職公務人員之年資為 3 年，因值勤受傷，辦理命令退休，如其請領一次退休金，退休年資應算幾年？","tableData":null,"images":[],"options":[{"key":"A","text":"3 年","imageUrl":null},{"key":"B","text":"5 年","imageUrl":null},{"key":"C","text":"20 年","imageUrl":null},{"key":"D","text":"35 年","imageUrl":null}],"correctAnswer":"B","explanation":"依公務人員退休資遣撫卹法規定，因公受傷辦理退休者，任職年資不滿5年者，以5年計。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_041","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"甲乙夫妻二人均為公務人員，膝下無子女，甲意外死亡，依公務人員退休資遣撫卹法規定，甲之遺族（妻乙及父母）領受遺族撫卹金之比例為何？","tableData":null,"images":[],"options":[{"key":"A","text":"乙再婚領撫卹金 1/2、甲父母各領撫卹金 1/4","imageUrl":null},{"key":"B","text":"乙未再婚領撫卹金 1/2、甲父母各領撫卹金 1/4","imageUrl":null},{"key":"C","text":"乙與甲父母各領撫卹金 1/3","imageUrl":null},{"key":"D","text":"得由乙與甲父母三人決定支領人及支領比例","imageUrl":null}],"correctAnswer":"B","explanation":"法律規定遺族領取比例，配偶支領1/2，其餘1/2由同一順序（父母）平均分配。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_042","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"下列何者不是公務人員協會法所定協商事項？","tableData":null,"images":[],"options":[{"key":"A","text":"給假","imageUrl":null},{"key":"B","text":"辦公環境之改善","imageUrl":null},{"key":"C","text":"行政管理","imageUrl":null},{"key":"D","text":"服勤之方式及起訖時間","imageUrl":null}],"correctAnswer":"C","explanation":"行政管理屬機關內部核心裁量權，依法不屬於公務人員協會得提出協商之事項。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_043","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"下列敘述何者屬於公務人員行政中立的內涵？","tableData":null,"images":[],"options":[{"key":"A","text":"公務人員原則上不得介入黨政紛爭，但如涉及本身權益，則不在限制範疇","imageUrl":null},{"key":"B","text":"事務官不得加入政黨或其他政治團體，更不得兼任政黨或其他政治團體之職務","imageUrl":null},{"key":"C","text":"公務人員應依法公正執行職務，不得對任何團體或個人予以差別待遇","imageUrl":null},{"key":"D","text":"公務人員不得於請假期間，從事政黨或其他政治團體之活動","imageUrl":null}],"correctAnswer":"C","explanation":"行政中立之核心精神在於公務員應超越政黨與利益群體，依法公正且不具偏見地執行公務。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_044","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"依公務員懲戒法規定，休職之懲戒處分，其懲戒處分行使期間為何？","tableData":null,"images":[],"options":[{"key":"A","text":"十年","imageUrl":null},{"key":"B","text":"五年","imageUrl":null},{"key":"C","text":"一年","imageUrl":null},{"key":"D","text":"未設期間","imageUrl":null}],"correctAnswer":"A","explanation":"休職之懲戒處分行使期間為10年，超過此期限後即不得行使。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_045","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"公務員服務法第 14 條之 1 規定，公務員於其離職後三年內，不得擔任與其離職前五年內之職務直接相關之營利事業董事、監察人、經理、執行業務之股東或顧問。本條規定行政學理稱之為何？","tableData":null,"images":[],"options":[{"key":"A","text":"「走後門」（back door）條款","imageUrl":null},{"key":"B","text":"「利害關係人」（stake holder）條款","imageUrl":null},{"key":"C","text":"「界線防守」（boundary spanning）條款","imageUrl":null},{"key":"D","text":"「旋轉門」（revolving door）條款","imageUrl":null}],"correctAnswer":"D","explanation":"限制公務員離職後轉任民間企業之相關職務，以防止利益輸送，行政學上稱為「旋轉門條款」。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_046","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"下列何者不是公務員服務法所規範的對象？","tableData":null,"images":[],"options":[{"key":"A","text":"臺北市市長","imageUrl":null},{"key":"B","text":"行政院院長","imageUrl":null},{"key":"C","text":"司法院大法官","imageUrl":null},{"key":"D","text":"未兼行政職之大學教授","imageUrl":null}],"correctAnswer":"D","explanation":"大學教授若未兼任行政職務，其行為受教育人員相關法令規範，不適用公務員服務法。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_047","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"公務人員不得利用職務上之權力、機會或方法，要求他人不行使投票權或為一定之行使，是為「妨害投票權行使之禁止」，下列何者不在禁止之範圍內？","tableData":null,"images":[],"options":[{"key":"A","text":"公職人員之選舉","imageUrl":null},{"key":"B","text":"公職人員之罷免","imageUrl":null},{"key":"C","text":"公民投票","imageUrl":null},{"key":"D","text":"公民聯署","imageUrl":null}],"correctAnswer":"D","explanation":"公民聯署非屬選罷法及行政中立法所明定之投票權行使禁止事項範疇。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_048","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"依據公務人員行政中立法，現職公務人員參與選舉活動之限制，下列敘述何者錯誤？","tableData":null,"images":[],"options":[{"key":"A","text":"公務人員登記為公職候選人，長官不得拒絕其請假","imageUrl":null},{"key":"B","text":"登記為公職候選人者，自候選人名單公告之日起至投票日止，不需要請假","imageUrl":null},{"key":"C","text":"照公平公正原則，裁量受理不受理各政治團體、公職候選人的申請事項","imageUrl":null},{"key":"D","text":"選舉公告日至投票日之選舉期間，應禁止各政治團體、公職候選人的造訪活動","imageUrl":null}],"correctAnswer":"B","explanation":"公務人員參加選舉時，自名單公告日至投票日應辦理請假，並非不需要請假。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_049","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"懲戒法庭對懲戒案件之審理，如認為懲戒處分牽涉刑事犯罪是否成立時，得於下列何種審別判決前停止審理程序？","tableData":null,"images":[],"options":[{"key":"A","text":"第一審刑事判決前","imageUrl":null},{"key":"B","text":"第二審刑事判決前","imageUrl":null},{"key":"C","text":"第三審刑事判決前","imageUrl":null},{"key":"D","text":"並無相關規定","imageUrl":null}],"correctAnswer":"A","explanation":"依公務員懲戒法規定，懲戒處分如牽涉刑事犯罪，得於第一審刑事判決前停止審理程序。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"},{"id":"110_110010_050","category":"chinese","stageId":"110_110010_506","type":"multiple-choice","difficulty":2,"text":"對於公務人員的基本義務，下列敘述何者正確？","tableData":null,"images":[],"options":[{"key":"A","text":"雙重國籍中，只要有中華民國國籍即可任用為公務人員","imageUrl":null},{"key":"B","text":"文官推動職務的匿名倫理要求，旨在應以職務或職稱對外評論決策","imageUrl":null},{"key":"C","text":"公務人員若依法有據，可以兼任公司代表官股之董事","imageUrl":null},{"key":"D","text":"公務人員只要在公餘時間從事教學工作，則不必經服務機關許可","imageUrl":null}],"correctAnswer":"C","explanation":"依公務員服務法規定，公務員除法律另有規定外不得兼職，但代表政府經營之營利事業董事為合法例外。","points":2,"tags":["110","110010","110年公務人員初等考試","初等考試","初等考試","506","人事行政","人事行政大意","測驗題"],"certificationType":"110年公務人員初等考試"}]');export{e as default};
